/**
 * The code points Noto Sans Hebrew maps (its cmap), so the layout knows before the font loads which characters it prints and which print
 * as "?". Generated by scripts/script-font-coverage.mjs from the font file; do not edit.
 *
 * Each range is "gap.length" in base 36: the gap after the previous range's last code point, and the range's length.
 */
export const NOTO_HEBREW_RANGES =
  '0.1 c.1 i.1 c.1 36.1 j2.1 g1.1j 8.r 4.6 55j.5 49.1 10h.1 164w.q 1.5 1.1 1.2 1.2 1.a xb.1';

/** How many code points the font maps. The test checks the table against the font with it. */
export const NOTO_HEBREW_CODE_POINTS = 148;
